import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import type { Db } from '../db/client.js';
import { createBookmark, deleteBookmark, getBookmark, updateBookmark } from '../db/repositories/bookmarks.js';
import { decodeCursor, searchBookmarks } from '../search/repository.js';
import { SearchSyntaxError } from '../search/parser.js';
import { problem, requireUser } from '../auth/plugin.js';
import type { Location, ReadState, SearchCriteria, Sort } from '../../shared/types.js';

const writeSchema=z.object({url:z.string().min(1).max(4096),title:z.string().min(1).max(200),description:z.string().max(2000).nullable().optional(),notesMarkdown:z.string().max(20000).nullable().optional(),siteIconUrl:z.string().url().nullable().optional(),previewImageUrl:z.string().url().nullable().optional(),metadataStatus:z.enum(['complete','partial','unavailable','blocked','timeout']).optional(),metadataWarnings:z.array(z.string()).max(20).optional(),tagIds:z.array(z.string().uuid()).max(100).optional(),collectionId:z.string().uuid().nullable().optional(),readState:z.enum(['unread','read']).optional()});
const patchSchema=writeSchema.partial().extend({expectedVersion:z.number().int().positive(),archived:z.boolean().optional()});

function criteria(query:any):SearchCriteria{return {query:String(query.q||'').slice(0,1001),location:(['active','unread','archive'].includes(query.location)?query.location:'active') as Location,tagIds:Array.isArray(query.tagId)?query.tagId:query.tagId?[query.tagId]:[],collectionId:query.collectionId||null,readState:(['read','unread'].includes(query.readState)?query.readState:null) as ReadState|null,sort:(['newest','oldest','title'].includes(query.sort)?query.sort:'newest') as Sort};}

export async function bookmarkRoutes(app:FastifyInstance,db:Db):Promise<void>{
  app.get('/api/bookmarks',async(request,reply)=>{const user=requireUser(request);const c=criteria(request.query as any);const limit=Math.min(100,Math.max(1,Number((request.query as any).limit)||50));try{const result=searchBookmarks(db,user.id,c,decodeCursor((request.query as any).cursor),limit);const current=(db.prepare('SELECT library_revision FROM users WHERE id=?').get(user.id) as any).library_revision;return {...result,criteria:c,libraryRevision:current,warnings:[]};}catch(error){if(error instanceof SearchSyntaxError)return reply.code(400).send(problem(400,'Invalid search',error.message,{start:error.start,end:error.end,query:c.query}));throw error;}});
  app.post('/api/bookmarks',async(request,reply)=>{const user=requireUser(request);const parsed=writeSchema.safeParse(request.body);if(!parsed.success)return reply.code(422).send(problem(422,'Validation failed',parsed.error.issues[0]?.message||'Check the bookmark fields.'));try{return reply.code(201).send(createBookmark(db,user.id,parsed.data));}catch(error:any){if(error.code==='DUPLICATE')return reply.code(409).send(problem(409,'Already saved',error.message,{existingBookmarkId:error.existingBookmarkId,archived:error.archived}));return reply.code(422).send(problem(422,'Could not save bookmark',error.message));}});
  app.get('/api/bookmarks/:id',async(request,reply)=>{const user=requireUser(request);return getBookmark(db,user.id,(request.params as any).id)??reply.code(404).send(problem(404,'Not found','That bookmark is unavailable.'));});
  app.patch('/api/bookmarks/:id',async(request,reply)=>{const user=requireUser(request);const parsed=patchSchema.safeParse(request.body);if(!parsed.success)return reply.code(422).send(problem(422,'Validation failed',parsed.error.issues[0]?.message||'Check the bookmark fields.'));try{const item=updateBookmark(db,user.id,(request.params as any).id,parsed.data.expectedVersion,parsed.data);return item??reply.code(404).send(problem(404,'Not found','That bookmark is unavailable.'));}catch(error:any){return reply.code(error.code==='STALE'||error.code==='DUPLICATE'?409:422).send(problem(error.code==='STALE'||error.code==='DUPLICATE'?409:422,'Could not update bookmark',error.message));}});
  app.delete('/api/bookmarks/:id',async(request,reply)=>{const user=requireUser(request);const version=Number((request.query as any).expectedVersion);if(!Number.isInteger(version))return reply.code(422).send(problem(422,'Validation failed','Expected bookmark version is required.'));const ok=deleteBookmark(db,user.id,(request.params as any).id,version);return ok?reply.code(204).send():reply.code(409).send(problem(409,'Bookmark changed','Refresh before deleting this bookmark.'));});
}

