export async function savedViewRoutes(app:FastifyInstance,db:Db){app.get('/api/saved-views',async r=>listViews(db,requireUser(r).id));app.post('/api/saved-views',async(r,p)=>{const u=requireUser(r),x=write.safeParse(r.body);if(!x.success)return p.code(422).send(problem(422,'Validation failed',x.error.issues[0].message));try{return p.code(201).send(saveView(db,u.id,x.data.name,x.data.criteria,x.data.replaceConflicting));}catch(e:any){return p.code(e.code==='NAME_CONFLICT'?409:422).send(problem(e.code==='NAME_CONFLICT'?409:422,'Could not save view',e.message));}});app.patch('/api/saved-views/:id',async(r,p)=>{const u=requireUser(r),x=write.safeParse(r.body);if(!x.success)return p.code(422).send(problem(422,'Validation failed',x.error.issues[0].message));try{return saveView(db,u.id,x.data.name,x.data.criteria,x.data.replaceConflicting,(r.params as any).id);}catch(e:any){return p.code(e.code==='NAME_CONFLICT'?409:422).send(problem(e.code==='NAME_CONFLICT'?409:422,'Could not update view',e.message));}});app.delete('/api/saved-views/:id',async(r,p)=>deleteView(db,requireUser(r).id,(r.params as any).id)?p.code(204).send():p.code(404).send(problem(404,'Not found','Saved view unavailable.')));}

