import crypto from 'node:crypto';
import type { Db } from '../client.js';
import type { SearchCriteria } from '../../../shared/types.js';
import { normalizeName } from '../../../shared/normalization.js';
import { parseSearch } from '../../search/parser.js';
import { revision } from './bookmarks.js';

type Row=Record<string,any>;
function map(db:Db,userId:number,row:Row){const criteria={query:row.raw_query,...JSON.parse(row.filters_json),location:row.location,sort:row.sort};const warnings:string[]=[];for(const id of criteria.tagIds||[]){if(!db.prepare('SELECT 1 FROM tags WHERE user_id=? AND public_id=?').get(userId,id))warnings.push('A referenced tag is no longer available.');}if(criteria.collectionId&&!db.prepare('SELECT 1 FROM collections WHERE user_id=? AND public_id=?').get(userId,criteria.collectionId))warnings.push('The referenced collection is no longer available.');return {id:row.public_id,name:row.name,criteria,parserVersion:row.parser_version,warnings,createdAt:row.created_at,updatedAt:row.updated_at};}
export function listViews(db:Db,userId:number){return (db.prepare('SELECT * FROM saved_views WHERE user_id=? ORDER BY name_key').all(userId) as Row[]).map((row)=>map(db,userId,row));}
export function saveView(db:Db,userId:number,name:string,criteria:SearchCriteria,replace=false,publicId?:string){const n=normalizeName(name);if([...n.display].length<1||[...n.display].length>50)throw new Error('Name must be between 1 and 50 characters.');if(criteria.query.length>1000)throw new Error('Search is limited to 1,000 characters.');const ast=parseSearch(criteria.query);const now=new Date().toISOString();return db.transaction(()=>{let id=publicId;const conflict=db.prepare('SELECT public_id FROM saved_views WHERE user_id=? AND name_key=?').get(userId,n.key) as Row|undefined;if(conflict&&conflict.public_id!==publicId){if(!replace){const e:any=new Error('A saved view with that name already exists.');e.code='NAME_CONFLICT';throw e;}id=conflict.public_id;}if(id){const result=db.prepare(`UPDATE saved_views SET name=?,name_key=?,raw_query=?,search_ast_json=?,filters_json=?,location=?,sort=?,updated_at=? WHERE user_id=? AND public_id=?`).run(n.display,n.key,criteria.query,JSON.stringify(ast),JSON.stringify({tagIds:criteria.tagIds,collectionId:criteria.collectionId,readState:criteria.readState}),criteria.location,criteria.sort,now,userId,id);if(!result.changes)throw new Error('Saved view not found.');}else{id=crypto.randomUUID();db.prepare(`INSERT INTO saved_views(public_id,user_id,name,name_key,raw_query,search_ast_json,filters_json,location,sort,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).run(id,userId,n.display,n.key,criteria.query,JSON.stringify(ast),JSON.stringify({tagIds:criteria.tagIds,collectionId:criteria.collectionId,readState:criteria.readState}),criteria.location,criteria.sort,now,now);}revision(db,userId);const row=db.prepare('SELECT * FROM saved_views WHERE user_id=? AND public_id=?').get(userId,id!) as Row;return map(db,userId,row);})();}
export function deleteView(db:Db,userId:number,id:string){return db.transaction(()=>{const r=db.prepare('DELETE FROM saved_views WHERE user_id=? AND public_id=?').run(userId,id);if(r.changes)revision(db,userId);return !!r.changes;})();}

