import { integer, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core';

export const users=sqliteTable('users',{id:integer().primaryKey({autoIncrement:true}),publicId:text('public_id').notNull().unique(),email:text().notNull().unique(),passwordHash:text('password_hash').notNull(),libraryRevision:integer('library_revision').notNull().default(0),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()});
export const collections=sqliteTable('collections',{id:integer().primaryKey({autoIncrement:true}),publicId:text('public_id').notNull().unique(),userId:integer('user_id').notNull().references(()=>users.id,{onDelete:'cascade'}),name:text().notNull(),nameKey:text('name_key').notNull(),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},table=>[uniqueIndex('collections_owner_name').on(table.userId,table.nameKey)]);
export const tags=sqliteTable('tags',{id:integer().primaryKey({autoIncrement:true}),publicId:text('public_id').notNull().unique(),userId:integer('user_id').notNull().references(()=>users.id,{onDelete:'cascade'}),name:text().notNull(),nameKey:text('name_key').notNull(),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},table=>[uniqueIndex('tags_owner_name').on(table.userId,table.nameKey)]);
export const bookmarks=sqliteTable('bookmarks',{id:integer().primaryKey({autoIncrement:true}),publicId:text('public_id').notNull().unique(),userId:integer('user_id').notNull().references(()=>users.id,{onDelete:'cascade'}),url:text().notNull(),normalizedUrl:text('normalized_url').notNull(),title:text().notNull(),description:text(),notesMarkdown:text('notes_markdown'),notesSearchText:text('notes_search_text').notNull(),siteIconUrl:text('site_icon_url'),previewImageUrl:text('preview_image_url'),metadataStatus:text('metadata_status').notNull(),metadataWarningsJson:text('metadata_warnings_json').notNull(),collectionId:integer('collection_id').references(()=>collections.id,{onDelete:'set null'}),readState:text('read_state').notNull(),archivedAt:text('archived_at'),titleSortKey:text('title_sort_key').notNull(),version:integer().notNull().default(1),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},table=>[uniqueIndex('bookmarks_owner_url').on(table.userId,table.normalizedUrl)]);
export const bookmarkTags=sqliteTable('bookmark_tags',{bookmarkId:integer('bookmark_id').notNull().references(()=>bookmarks.id,{onDelete:'cascade'}),tagId:integer('tag_id').notNull().references(()=>tags.id,{onDelete:'cascade'}),createdAt:text('created_at').notNull()});
export const savedViews=sqliteTable('saved_views',{id:integer().primaryKey({autoIncrement:true}),publicId:text('public_id').notNull().unique(),userId:integer('user_id').notNull().references(()=>users.id,{onDelete:'cascade'}),name:text().notNull(),nameKey:text('name_key').notNull(),rawQuery:text('raw_query').notNull(),searchAstJson:text('search_ast_json').notNull(),filtersJson:text('filters_json').notNull(),location:text().notNull(),sort:text().notNull(),parserVersion:integer('parser_version').notNull().default(1),createdAt:text('created_at').notNull(),updatedAt:text('updated_at').notNull()},table=>[uniqueIndex('saved_views_owner_name').on(table.userId,table.nameKey)]);

