d':'Bookmarks'}</h1><p>{page.total} {page.total===1?'bookmark':'bookmarks'}{criteria.query?' matching your search':''}</p></div><button className="primary desktop-add" onClick={()=>setForm(true)}><Icon name="plus"/>Add bookmark</button></div><div className="toolbar"><div className="searchbox"><Icon name="search"/><input aria-label="Search bookmarks" value={criteria.query} onChange={e=>setCriteria(c=>({...c,query:e.target.value}))} placeholder={'Search words, "exact phrases", tag:research…'}/>{criteria.query&&<button onClick={()=>setCriteria(c=>({...c,query:''}))}>×</button>}</div><select aria-label="Filter by tag" value="" onChange={e=>e.target.value&&setCriteria(c=>({...c,tagIds:[...new Set([...c.tagIds,e.target.value])]}))}><option value="">Tag filter</option>{tags.filter(t=>!criteria.tagIds.includes(t.id)).map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><select aria-label="Filter by collection" value={criteria.collectionId||''} onChange={e=>setCriteria(c=>({...c,collectionId:e.target.value||null}))}><option value="">All collections</option>{collections.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select aria-label="Sort bookmarks" value={criteria.sort} onChange={e=>setCriteria(c=>({...c,sort:e.target.value as Sort}))}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></div>{criteria.tagIds.length>0&&<div className="active-filters">{criteria.tagIds.map(id=><button key={id} className="tag" onClick={()=>setCriteria(c=>({...c,tagIds:c.tagIds.filter(x=>x!==id)}))}>#{tags.find(t=>t.id===id)?.name||'Unavailable'} ×</button>)}<button className="link" onClick={()=>setCriteria(c=>({...c,tagIds:[],collectionId:null,readState:null,query:''}))}>Clear all</button></div>}{message&&<div className="notice error" role="alert">{message}</div>}{loading?<div className="loading-grid">Loading your library…</div>:page.items.length===0?<div className="empty"><div className="empty-icon"><Icon name={criteria.location==='archive'?'archive':'bookmark'}/></div><h2>{criteria.query||criteria.tagIds.length?'Nothing matches yet':criteria.location==='unread'?'Your unread queue is clear':criteria.location==='archive'?'Nothing set aside':'Your library is waiting'}</h2><p>{criteria.query||criteria.tagIds.length?'Try broadening the search or clearing a filter.':'Save your first link and let Latch fill in the useful details.'}</p>{!criteria.query&&!criteria.tagIds.length&&criteria.location==='active'&&<button className="primary" onClick={()=>setForm(true)}>Add your first bookmark</button>}</div>:<><div className="list-actions"><label><input type="checkbox" checked={page.items.length>0&&page.items.every(i=>selected.includes(i.id))} onChange={e=>setSelected(e.target.checked?page.items.map(i=>i.id):[])}/> Select this page</label></div><section className="bookmark-grid">{page.items.map(item=><BookmarkCard key={item.id} item={item} selected={selected.includes(item.id)} onSelect={yes=>setSelected(s=>yes?[...new Set([...s,item.id])]:s.filter(id=>id!==item.id))} onEdit={()=>setForm(item)} onChanged={()=>{load();loadLabels()}}/>)}</section></>}<BulkBar selected={selected} total={page.total} allMatching={allMatching} setAllMatching={setAllMatching} clear={()=>{setSelected([]);setAllMatching(false)}} criteria={criteria} tags={tags} onDone={()=>{load();loadLabels()}}/></main></div>{form&&<BookmarkForm bookmark={form===true?undefined:form} tags={tags} collections={collections} onClose={()=>setForm(null)} onSaved={()=>{load();loadLabels()}}/>}{organize&&<Organization tags={tags} collections={collections} refresh={loadLabels} onClose={()=>setOrganize(false)}/>}</div>}
