type Criteria={query:string;location:Location;tagIds:string[];collectionId:string|null;readState:ReadState|null;sort:Sort};
type Bookmark={id:string;url:string;normalizedUrl:string;title:string;description:string|null;notesMarkdown:string|null;siteIconAvailable:boolean;previewImageAvailable:boolean;metadataStatus:string;metadataWarnings:string[];tagIds:string[];tags:{id:string;name:string}[];collectionId:string|null;collectionName:string|null;readState:ReadState;archived:boolean;archivedAt:string|null;version:number;createdAt:string;updatedAt:string};
