ion value="">Add tag…</option>{tags.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><select aria-label="Remove tag in bulk" defaultValue="" onChange={e=>{if(e.target.value)run('removeTags',[e.target.value]);e.target.value=''}}><option value="">Remove tag…</option>{tags.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><button className="danger-text" onClick={()=>run('deletePermanently')} disabled={busy}>Delete permanently</button><button className="icon-button" onClick={clear} aria-label="Clear selection"><Icon name="x"/></button></aside>}

