function Login({onLogin}:{onLogin:(s:any)=>void}){const[email,setEmail]=useState('review@example.test');const[password,setPassword]=useState('bookmark-review');const[error,setError]=useState('');const[busy,setBusy]=useState(false);async function submit(e:any){e.preventDefault();setBusy(true);setError('');try{const s=await api<any>('/session/login',{method:'POST',body:JSON.stringify({email,password})});setCsrf(s.csrfToken);onLogin(s);}catch(e){setError(e instanceof Error?e.message:'Sign in failed.');}finally{setBusy(false);}}return <main className="login-page"><section className="login-card"><div className="brand-mark"><Icon name="bookmark"/></div><p className="eyebrow">YOUR PERSONAL LIBRARY</p><h1>Hold on to what matters.</h1><p className="lede">Save thoughtful reads, useful references, and sparks worth returning to.</p><form onSubmit={submit}><label>Email<input value={email} onChange={e=>setEmail(e.target.value)} type="email" autoComplete="username"/></label><label>Password<input value={password} onChange={e=>setPassword(e.target.value)} type="password" autoComplete="current-password"/></label>{error&&<p className="error" role="alert">{error}</p>}<button className="primary wide" disabled={busy}>{busy?'Opening your library…':'Enter library'}</button></form><p className="fine">Private by design. Your bookmarks stay yours.</p></section></main>}

function BookmarkForm({bookmark,tags,collections,onClose,onSaved}:{bookmark?:Bookmark;tags:Label[];collections:Label[];onClose:()=>void;onSaved:()=>void}){const[form,setForm]=useState({url:bookmark?.url||'',title:bookmark?.title||'',description:bookmark?.description||'',notesMarkdown:bookmark?.notesMarkdown||'',readState:bookmark?.readState||'unread',collectionId:bookmark?.collectionId||'',tagIds:bookmark?.tagIds||[],siteIconUrl:null as string|null,previewImageUrl:null as string|null,metadataStatus:(bookmark?.metadataStatus||'unavailable'),metadataWarnings:[]as string[]});const[preview,setPreview]=useState<any>(null);const[busy,setBusy]=useState(false);const[message,setMessage]=useState('');const timer=useRef<any>(null);const changed=useRef({title:!!bookmark?.title,description:!!bookmark?.description});useEffect(()=>()=>clearTimeout(timer.current),[]);async function fetchDetails(url=form.url){if(!url.trim())return;setMessage('Looking up page details…');try{const data=await api<any>('/metadata-preview',{method:'POST',body:JSON.stringify({url})});setPreview(data);setForm(old=>({...old,url:data.normalizedUrl,title:changed.current.title?old.title:data.title,description:changed.current.description?old.description:(data.description||''),siteIconUrl:data.siteIconUrl,previewImageUrl:data.previewImageUrl,metadataStatus:data.status,metadataWarnings:data.warnings}));setMessage(data.status==='complete'?'Details found.':data.warnings[0]||'Some details were unavailable—you can still save.');}catch(e){setMessage(e instanceof Error?`${e.message} You can still enter details manually.`:'Details unavailable.');}}function urlChanged(value:string){setForm(f=>({...f,url:value}));clearTimeout(timer.current);timer.current=setTimeout(()=>fetchDetails(value),700);}async function addTypedTag(value:string){const name=value.trim();if(!name)return;let found=tags.find(t=>t.name.toLowerCase()===name.toLowerCase());if(!found){try{found=await api<Label>('/tags',{method:'POST',body:JSON.stringify({name})});}catch(e){setMessage(e instanceof Error?e.message:'Could not create tag.');return;}}setForm(f=>({...f,tagIds:[...new Set([...f.tagIds,found!.id])]}));}
async function save(e:any){e.preventDefault();setBusy(true);setMessage('');const body={...form,collectionId:form.collectionId||null,description:form.description||null,notesMarkdown:form.notesMarkdown||null,...(bookmark?{expectedVersion:bookmark.version}:{})};try{await api(bookmark?`/bookmarks/${bookmark.id}`:'/bookmarks',{method:bookmark?'PATCH':'POST',body:JSON.stringify(body)});onSaved();onClose();}catch(e){if(e instanceof ApiError&&e.status===409&&e.body.existingBookmarkId)setMessage(`Already saved${e.body.archived?' in Archive':''}. Open the existing bookmark instead.`);else setMessage(e instanceof Error?e.message:'Could not save bookmark.');}finally{setBusy(false);}}
return <div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="form-title"><header><div><p className="eyebrow">{bookmark?'UPDATE ENTRY':'NEW BOOKMARK'}</p><h2 id="form-title">{bookmark?'Edit bookmark':'Save something worth keeping'}</h2></div><button className="icon-button" aria-label="Close" onClick={onClose}><Icon name="x"/></button></header><form onSubmit={save}><label>Web address<div className="url-row"><input required maxLength={4096} value={form.url} onChange={e=>urlChanged(e.target.value)} placeholder="https://example.com/article"/><button type="button" className="secondary" onClick={()=>fetchDetails()}>Fetch details</button></div></label>{message&&<p className="status" role="status">{message}</p>}{preview?.previewImageProxyUrl&&<div className="metadata-preview"><img src={preview.previewImageProxyUrl} alt=""/><span>{preview.finalUrl}</span></div>}<div className="form-grid"><label>Title<input required maxLength={200} value={form.title} onChange={e=>{changed.current.title=true;setForm(f=>({...f,title:e.target.value}))}}/></label><label>Status<select value={form.readState} onChange={e=>setForm(f=>({...f,readState:e.target.value as ReadState}))}><option value="unread">Unread — read later</option><option value="read">Read</option></select></label></div><label>Short description<textarea maxLength={2000} rows={2} value={form.description} onChange={e=>{changed.current.description=true;setForm(f=>({...f,description:e.target.value}))}}/></label><div className="form-grid"><label>Collection<select value={form.collectionId} onChange={e=>setForm(f=>({...f,collectionId:e.target.value}))}><option value="">No collection</option>{collections.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Add a tag<TagAdder tags={tags} onAdd={addTypedTag}/></label></div><div className="selected-tags">{form.tagIds.map(id=>{const t=tags.find(x=>x.id===id);return t&&<button type="button" className="tag" key={id} onClick={()=>setForm(f=>({...f,tagIds:f.tagIds.filter(x=>x!==id)}))}>{t.name} ×</button>})}</div><label>Personal notes <span className="hint">Markdown supported · {form.notesMarkdown.length}/20,000</span><textarea maxLength={20000} rows={7} value={form.notesMarkdown} onChange={e=>setForm(f=>({...f,notesMarkdown:e.target.value}))} placeholder={'## Why I saved this\n\n- Key idea\n- Follow up later'}/></label>{form.notesMarkdown&&<details><summary>Preview notes</summary><SafeMarkdown>{form.notesMarkdown}</SafeMarkdown></details>}<footer><button type="button" className="ghost" onClick={onClose}>Cancel</button><button className="primary" disabled={busy||!form.url||!form.title}>{busy?'Saving…':bookmark?'Save changes':'Save bookmark'}</button></footer></form></section></div>}

function TagAdder({tags,onAdd}:{tags:Label[];onAdd:(v:string)=>void}){const[value,setValue]=useState('');const suggestions=tags.filter(t=>t.name.toLowerCase().includes(value.toLowerCase())).slice(0,6);return <div className="tag-adder"><input value={value} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();onAdd(value);setValue('')}}} placeholder="Type and press Enter" list="tag-suggestions"/><datalist id="tag-suggestions">{suggestions.map(t=><option key={t.id} value={t.name}/>)}</datalist></div>}

function BookmarkCard({item,selected,onSelect,onEdit,onChanged}:{item:Bookmark;selected:boolean;onSelect:(v:boolean)=>void;onEdit:()=>void;onChanged:()=>void}){const[open,setOpen]=useState(false);async function patch(p:any){await api(`/bookmarks/${item.id}`,{method:'PATCH',body:JSON.stringify({expectedVersion:item.version,...p})});onChanged();}async function remove(){if(!confirm(`Permanently delete “${item.title}”? This cannot be undone.`))return;await api(`/bookmarks/${item.id}?expectedVersion=${item.version}`,{method:'DELETE'});onChanged();}return <article className={`bookmark-card ${selected?'selected':''}`}><div className="card-media">{item.previewImageAvailable?<img src={`/api/bookmarks/${item.id}/assets/preview`} alt=""/>:<div className="media-fallback"><span>{new URL(item.url).hostname.slice(0,1).toUpperCase()}</span></div>}<label className="select-box"><input type="checkbox" checked={selected} onChange={e=>onSelect(e.target.checked)}/><span className="sr-only">Select {item.title}</span></label>{item.readState==='unread'&&<span className="unread-dot" title="Unread"/>}</div><div className="card-body"><div className="site-line">{item.siteIconAvailable&&<img src={`/api/bookmarks/${item.id}/assets/icon`} alt=""/>}<span>{new URL(item.url).hostname}</span><span>·</span><time>{new Date(item.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time></div><h3><a href={item.url} target="_blank" rel="noopener noreferrer">{item.title}</a></h3>{item.description&&<p className="description">{item.description}</p>}<div className="chips">{item.collectionName&&<span className="collection">{item.collectionName}</span>}{item.tags.map(t=><span className="tag" key={t.id}>#{t.name}</span>)}</div>{open&&item.notesMarkdown&&<SafeMarkdown>{item.notesMarkdown}</SafeMarkdown>}<footer><button className="text-button" onClick={()=>patch({readState:item.readState==='read'?'unread':'read'})}><Icon name="check"/>{item.readState==='read'?'Mark unread':'Mark read'}</button>{item.notesMarkdown&&<button className="text-button" onClick={()=>setOpen(!open)}><Icon name="eye"/>{open?'Hide notes':'Notes'}</button>}<div className="spacer"/><button className="icon-button" title="Edit" onClick={onEdit}><Icon name="edit"/></button><button className="icon-button" title={item.archived?'Restore':'Archive'} onClick={()=>patch({archived:!item.archived})}><Icon name="archive"/></button><button className="icon-button danger" title="Delete permanently" onClick={remove}><Icon name="trash"/></button></footer></div></article>}

function BulkBar({selected,total,allMatching,setAllMatching,clear,criteria,tags,onDone}:{selected:string[];total:number;allMatching:boolean;setAllMatching:(v:boolean)=>void;clear:()=>void;criteria:Criteria;tags:Label[];onDone:()=>void}){const[busy,setBusy]=useState(false);if(!selected.length&&!allMatching)return null;const count=allMatching?total:selected.length;async function run(type:string,tagIds?:string[]){setBusy(true);try{const selection=allMatching?{mode:'allMatching',criteria}:{mode:'explicit',bookmarkIds:selected};const action={type,tagIds};const preview=await api<any>('/bulk-actions/preview',{method:'POST',body:JSON.stringify({selection,action})});const destructive=type==='deletePermanently';if(!confirm(`${destructive?'Permanently delete':'Apply this action to'} ${preview.matchedCount} bookmark${preview.matchedCount===1?'':'s'}?${destructive?' This cannot be undone.':''}`))return;const result=await api<any>('/bulk-actions/execute',{method:'POST',body:JSON.stringify({selection,action,criteriaHash:preview.criteriaHash,libraryRevision:preview.libraryRevision,expectedCount:preview.matchedCount,confirmed:true})});alert(`${result.succeededCount} updated${result.failedCount?`; ${result.failedCount} failed`:''}.`);clear();onDone();}catch(e){alert(e instanceof Error?e.message:'Bulk action failed.');}finally{setBusy(false);}}return <aside className="bulk-bar" aria-live="polite"><strong>{count} selected</strong>{!allMatching&&selected.length<total&&<button className="link" onClick={()=>setAllMatching(true)}>Select all {total} matches</button>}<button onClick={()=>run('markRead')} disabled={busy}>Read</button><button onClick={()=>run('markUnread')} disabled={busy}>Unread</button><button onClick={()=>run(criteria.location==='archive'?'restore':'archive')} disabled={busy}>{criteria.location==='archive'?'Restore':'Archive'}</button><select aria-label="Add tag in bulk" defaultValue="" onChange={e=>{if(e.target.value)run('addTags',[e.target.value]);e.target.value=''}}><option value="">Add tag…</option>{tags.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><select aria-label="Remove tag in bulk" defaultValue="" onChange={e=>{if(e.target.value)run('removeTags',[e.target.value]);e.target.value=''}}><option value="">Remove tag…</option>{tags.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><button className="danger-text" onClick={()=>run('deletePermanently')} disabled={busy}>Delete permanently</button><button className="icon-button" onClick={clear} aria-label="Clear selection"><Icon name="x"/></button></aside>}

function Organization({tags,collections,refresh,onClose}:{tags:Label[];collections:Label[];refresh:()=>void;onClose:()=>void}){const[name,setName]=useState('');const[kind,setKind]=useState<'tags'|'collections'>('tags');async function add(){if(!name.trim())return;await api(`/${kind}`,{method:'POST',body:JSON.stringify({name})});setName('');refresh();}async function rename(item:Label){const next=prompt(`Rename “${item.name}”`,item.name);if(!next||next===item.name)return;await api(`/${kind}/${item.id}`,{method:'PATCH',body:JSON.stringify({name:next})});refresh();}async function remove(item:Label){if(!confirm(`Remove “${item.name}” from ${item.bookmarkCount} bookmark${item.bookmarkCount===1?'':'s'}? The bookmarks will be kept.`))return;await api(`/${kind}/${item.id}?expectedCount=${item.bookmarkCount}`,{method:'DELETE'});refresh();}const items=kind==='tags'?tags:collections;return <div className="modal-backdrop"><section className="modal small"><header><div><p className="eyebrow">ORGANIZE</p><h2>Tags & collections</h2></div><button className="icon-button" onClick={onClose}><Icon name="x"/></button></header><div className="tabs"><button className={kind==='tags'?'active':''} onClick={()=>setKind('tags')}>Tags</button><button className={kind==='collections'?'active':''} onClick={()=>setKind('collections')}>Collections</button></div><div className="url-row"><input value={name} maxLength={50} onChange={e=>setName(e.target.value)} placeholder={`New ${kind==='tags'?'tag':'collection'} name`}/><button className="primary" onClick={add}>Add</button></div><div className="label-list">{items.map(item=><div key={item.id}><span>{item.name}</span><small>{item.bookmarkCount} bookmark{item.bookmarkCount===1?'':'s'}</small><button className="icon-button" aria-label={`Rename ${item.name}`} onClick={()=>rename(item)}><Icon name="edit"/></button><button className="icon-button danger" aria-label={`Delete ${item.name}`} onClick={()=>remove(item)}><Icon name="trash"/></button></div>)}</div></section></div>}

export default function App(){const[session,setSession]=useState<any>(null);const[ready,setReady]=useState(false);const[criteria,setCriteria]=useState<Criteria>(emptyCriteria);const[page,setPage]=useState<Page>({items:[],total:0,nextCursor:null,criteria:emptyCriteria,libraryRevision:0,warnings:[]});const[tags,setTags]=useState<Label[]>([]);const[collections,setCollections]=useState<Label[]>([]);const[views,setViews]=useState<View[]>([]);const[form,setForm]=useState<Bookmark|true|null>(null);const[organize,setOrganize]=useState(false);const[selected,setSelected]=useState<string[]>([]);const[allMatching,setAllMatching]=useState(false);const[message,setMessage]=useState('');const[loading,setLoading]=useState(false);
const loadLabels=useCallback(async()=>{const[t,c,v]=await Promise.all([api<Label[]>('/tags'),api<Label[]>('/collections'),api<View[]>('/saved-views')]);setTags(t);setCollections(c);setViews(v);},[]);
const load=useCallback(async(c=criteria)=>{setLoading(true);try{const params=new URLSearchParams({q:c.query,location:c.location,sort:c.sort,limit:'50'});c.tagIds.forEach(id=>params.append('tagId',id));if(c.collectionId)params.set('collectionId',c.collectionId);if(c.readState)params.set('readState',c.readState);const data=await api<Page>(`/bookmarks?${params}`);setPage(data);setMessage('');}catch(e){setMessage(e instanceof Error?e.message:'Could not load bookmarks.');}finally{setLoading(false);}},[criteria]);
useEffect(()=>{api<any>('/session').then(s=>{setCsrf(s.csrfToken);setSession(s);return Promise.all([load(),loadLabels()]);}).catch(()=>{}).finally(()=>{setReady(true)});},[]);
useEffect(()=>{if(session){const t=setTimeout(()=>load(criteria),180);return()=>clearTimeout(t)}},[criteria,session]);
useEffect(()=>{setSelected([]);setAllMatching(false)},[criteria]);
async function logout(){await api('/session',{method:'DELETE'});setSession(null);}
async function saveView(){const name=prompt('Name this view');if(!name)return;try{await api('/saved-views',{method:'POST',body:JSON.stringify({name,criteria})});await loadLabels();}catch(e){if(e instanceof ApiError&&e.status===409&&confirm('A view with that name exists. Replace it?')){await api('/saved-views',{method:'POST',body:JSON.stringify({name,criteria,replaceConflicting:true})});await loadLabels();}else alert(e instanceof Error?e.message:'Could not save view.');}}
async function renameView(view:View){const name=prompt(`Rename “${view.name}”`,view.name);if(!name||name===view.name)return;await api(`/saved-views/${view.id}`,{method:'PATCH',body:JSON.stringify({name,criteria:view.criteria})});await loadLabels();}
if(!ready)return <main className="loading-screen"><div className="brand-mark"><Icon name="bookmark"/></div><p>Opening your library…</p></main>;
if(!session)return <Login onLogin={s=>{setSession(s);setCsrf(s.csrfToken);load();loadLabels();}}/>;
return <div className="app" data-harness-ready="true"><header className="topbar"><a className="brand" href="#" onClick={()=>setCriteria({...emptyCriteria,location:'active'})}><span className="brand-mark small"><Icon name="bookmark"/></span><span>Latch</span></a><nav aria-label="Main navigation"><button className={criteria.location==='active'?'active':''} onClick={()=>setCriteria(c=>({...c,location:'active'}))}>Library</button><button className={criteria.location==='unread'?'active':''} onClick={()=>setCriteria(c=>({...c,location:'unread'}))}>Unread</button><button className={criteria.location==='archive'?'active':''} onClick={()=>setCriteria(c=>({...c,location:'archive'}))}>Archive</button></nav><div className="account"><span>{session.user.email}</span><button className="ghost" onClick={logout}>Sign out</button></div></header><div className="shell"><aside className="sidebar"><button className="primary wide" onClick={()=>setForm(true)}><Icon name="plus"/> Add bookmark</button><section><h2>Saved views</h2>{views.length===0?<p className="muted">Your frequent searches will live here.</p>:views.map(v=><div className="saved-row" key={v.id}><button onClick={()=>setCriteria(v.criteria)}>{v.name}{v.warnings.length>0&&' ⚠'}</button><button aria-label={`Rename ${v.name}`} onClick={()=>renameView(v)}>✎</button><button aria-label={`Delete ${v.name}`} onClick={async()=>{await api(`/saved-views/${v.id}`,{method:'DELETE'});loadLabels()}}>×</button></div>)}<button className="text-button" onClick={saveView}>+ Save current view</button></section><section><h2>Browse</h2><button className="side-link" onClick={()=>setOrganize(true)}><Icon name="tag"/> Tags & collections</button></section></aside><main className="content"><div className="page-heading"><div><p className="eyebrow">{criteria.location==='archive'?'SET ASIDE':criteria.location==='unread'?'READ IT LATER':'YOUR LIBRARY'}</p><h1>{criteria.location==='archive'?'Archive':criteria.location==='unread'?'Unread':'Bookmarks'}</h1><p>{page.total} {page.total===1?'bookmark':'bookmarks'}{criteria.query?' matching your search':''}</p></div><button className="primary desktop-add" onClick={()=>setForm(true)}><Icon name="plus"/>Add bookmark</button></div><div className="toolbar"><div className="searchbox"><Icon name="search"/><input aria-label="Search bookmarks" value={criteria.query} onChange={e=>setCriteria(c=>({...c,query:e.target.value}))} placeholder={'Search words, "exact phrases", tag:research…'}/>{criteria.query&&<button onClick={()=>setCriteria(c=>({...c,query:''}))}>×</button>}</div><select aria-label="Filter by tag" value="" onChange={e=>e.target.value&&setCriteria(c=>({...c,tagIds:[...new Set([...c.tagIds,e.target.value])]}))}><option value="">Tag filter</option>{tags.filter(t=>!criteria.tagIds.includes(t.id)).map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select><select aria-label="Filter by collection" value={criteria.collectionId||''} onChange={e=>setCriteria(c=>({...c,collectionId:e.target.value||null}))}><option value="">All collections</option>{collections.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select aria-label="Sort bookmarks" value={criteria.sort} onChange={e=>setCriteria(c=>({...c,sort:e.target.value as Sort}))}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></div>{criteria.tagIds.length>0&&<div className="active-filters">{criteria.tagIds.map(id=><button key={id} className="tag" onClick={()=>setCriteria(c=>({...c,tagIds:c.tagIds.filter(x=>x!==id)}))}>#{tags.find(t=>t.id===id)?.name||'Unavailable'} ×</button>)}<button className="link" onClick={()=>setCriteria(c=>({...c,tagIds:[],collectionId:null,readState:null,query:''}))}>Clear all</button></div>}{message&&<div className="notice error" role="alert">{message}</div>}{loading?<div className="loading-grid">Loading your library…</div>:page.items.length===0?<div className="empty"><div className="empty-icon"><Icon name={criteria.location==='archive'?'archive':'bookmark'}/></div><h2>{criteria.query||criteria.tagIds.length?'Nothing matches yet':criteria.location==='unread'?'Your unread queue is clear':criteria.location==='archive'?'Nothing set aside':'Your library is waiting'}</h2><p>{criteria.query||criteria.tagIds.length?'Try broadening the search or clearing a filter.':'Save your first link and let Latch fill in the useful details.'}</p>{!criteria.query&&!criteria.tagIds.length&&criteria.location==='active'&&<button className="primary" onClick={()=>setForm(true)}>Add your first bookmark</button>}</div>:<><div className="list-actions"><label><input type="checkbox" checked={page.items.length>0&&page.items.every(i=>selected.includes(i.id))} onChange={e=>setSelected(e.target.checked?page.items.map(i=>i.id):[])}/> Select this page</label></div><section className="bookmark-grid">{page.items.map(item=><BookmarkCard key={item.id} item={item} selected={selected.includes(item.id)} onSelect={yes=>setSelected(s=>yes?[...new Set([...s,item.id])]:s.filter(id=>id!==item.id))} onEdit={()=>setForm(item)} onChanged={()=>{load();loadLabels()}}/>)}</section></>}<BulkBar selected={selected} total={page.total} allMatching={allMatching} setAllMatching={setAllMatching} clear={()=>{setSelected([]);setAllMatching(false)}} criteria={criteria} tags={tags} onDone={()=>{load();loadLabels()}}/></main></div>{form&&<BookmarkForm bookmark={form===true?undefined:form} tags={tags} collections={collections} onClose={()=>setForm(null)} onSaved={()=>{load();loadLabels()}}/>}{organize&&<Organization tags={tags} collections={collections} refresh={loadLabels} onClose={()=>setOrganize(false)}/>}</div>}
import dns from 'node:dns/promises';
import { Agent, request } from 'undici';
import ipaddr from 'ipaddr.js';
import { config } from '../config.js';

export class FetchBlockedError extends Error {}
export class FetchTimeoutError extends Error {}

export interface SafeFetchResult {
  finalUrl: string;
  contentType: string;
  body: Buffer;
  redirects: number;
}

function isPublicAddress(value: string): boolean {
  try {
    let address = ipaddr.parse(value);
    if (address.kind() === 'ipv6') {
      const ipv6 = address as ipaddr.IPv6;
      if (ipv6.isIPv4MappedAddress()) address = ipv6.toIPv4Address();
    }
    return address.range() === 'unicast';
  } catch {
    return false;
  }
}

export async function resolvePublic(url: URL): Promise<Array<{ address: string; family: number }>> {
  if (!['http:', 'https:'].includes(url.protocol)) throw new FetchBlockedError('Only HTTP and HTTPS destinations are allowed.');
  if (url.username || url.password) throw new FetchBlockedError('Destinations containing credentials are blocked.');
  if (url.port && !['80', '443'].includes(url.port)) throw new FetchBlockedError('Only standard web ports are allowed.');
  const records = await dns.lookup(url.hostname, { all: true, order: 'verbatim' });
  if (!records.length || records.some((record) => !isPublicAddress(record.address))) {
    throw new FetchBlockedError('The destination does not resolve exclusively to public addresses.');
  }
  return records;
}

export async function safeFetch(
  input: string,
  options: { maxBytes?: number; accept?: string; allowedTypes?: RegExp } = {},
): Promise<SafeFetchResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), config.metadata.deadlineMs);
  let current = new URL(input);
  const visited = new Set<string>();
  try {
    for (let redirects = 0; redirects <= config.metadata.maxRedirects; redirects++) {
      if (visited.has(current.href)) throw new FetchBlockedError('The destination redirects in a loop.');
      visited.add(current.href);
      const records = await resolvePublic(current);
      const selected = records[0];
      const dispatcher = new Agent({
        maxResponseSize: options.maxBytes ?? config.metadata.maxHtmlBytes,
        connect: {
          timeout: 1500,
          lookup: (_hostname, _options, callback) => callback(null, selected.address, selected.family),
        },
      });
      try {
        const response = await request(current, {
          method: 'GET',
          dispatcher,
          signal: controller.signal,
          headersTimeout: 2500,
          bodyTimeout: 2500,
          headers: {
            accept: options.accept || 'text/html,application/xhtml+xml',
            'accept-encoding': 'identity',
            'user-agent': 'LatchBookmarkPreview/1.0',
          },
        });
        if ([301, 302, 303, 307, 308].includes(response.statusCode)) {
          const location = response.headers.location;
          await response.body.dump();
          if (!location) throw new FetchBlockedError('Redirect response has no destination.');
          if (redirects === config.metadata.maxRedirects) throw new FetchBlockedError('Too many redirects.');
          current = new URL(Array.isArray(location) ? location[0] : location, current);
          continue;
        }
        if (response.statusCode < 200 || response.statusCode >= 300) {
          await response.body.dump();
          throw new Error(`Publisher returned HTTP ${response.statusCode}.`);
        }
        const contentType = String(response.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
        if (options.allowedTypes && !options.allowedTypes.test(contentType)) {
          await response.body.dump();
          throw new Error('Publisher returned an unsupported content type.');
        }
        const bytes = Buffer.from(await response.body.arrayBuffer());
        return { finalUrl: current.href, contentType, body: bytes, redirects };
      } finally {
        await dispatcher.close();
      }
    }
    throw new FetchBlockedError('Too many redirects.');
  } catch (error) {
    if (controller.signal.aborted) throw new FetchTimeoutError('The publisher did not respond in time.');
    throw error;
  } finally {
    clearTimeout(timer);
  }
}
import crypto from 'node:crypto';
import type { Db } from '../db/client.js';
import type { SearchCriteria } from '../../shared/types.js';
import { deleteBookmark, getBookmark, updateBookmark } from '../db/repositories/bookmarks.js';
import { searchBookmarks } from '../search/repository.js';

export type BulkAction={type:'markRead'|'markUnread'|'archive'|'restore'|'addTags'|'removeTags'|'deletePermanently';tagIds?:string[]};
export type Selection={mode:'explicit';bookmarkIds:string[]}|{mode:'allMatching';criteria:SearchCriteria};

function canonical(selection:Selection,action:BulkAction){const normalized=selection.mode==='explicit'?{...selection,bookmarkIds:[...new Set(selection.bookmarkIds)].sort()}:selection;return JSON.stringify({selection:normalized,action:{...action,tagIds:action.tagIds?[...new Set(action.tagIds)].sort():undefined}});}
function targets(db:Db,userId:number,selection:Selection){if(selection.mode==='explicit')return [...new Set(selection.bookmarkIds)].map(id=>getBookmark(db,userId,id)).filter(Boolean) as NonNullable<ReturnType<typeof getBookmark>>[];return searchBookmarks(db,userId,selection.criteria,0,10000).items;}
function currentRevision(db:Db,userId:number){return Number((db.prepare('SELECT library_revision FROM users WHERE id=?').get(userId) as any).library_revision);}
export function previewBulk(db:Db,userId:number,selection:Selection,action:BulkAction){const items=targets(db,userId,selection);return{criteriaHash:crypto.createHash('sha256').update(canonical(selection,action)).digest('hex'),libraryRevision:currentRevision(db,userId),matchedCount:items.length,applicableCount:items.length,rejectedCount:0,requiresConfirmation:true,rejectionSummary:[]};}
export function executeBulk(db:Db,userId:number,selection:Selection,action:BulkAction,expected:{criteriaHash:string;libraryRevision:number;expectedCount:number}){return db.transaction(()=>{const preview=previewBulk(db,userId,selection,action);if(preview.criteriaHash!==expected.criteriaHash||preview.libraryRevision!==expected.libraryRevision||preview.matchedCount!==expected.expectedCount){const e:any=new Error('The matching bookmarks changed. Review the updated count before continuing.');e.code='STALE_BULK';throw e;}const items=targets(db,userId,selection);const failures:Array<{bookmarkId:string;reason:string}>=[];let succeeded=0;for(const item of items){try{if(action.type==='deletePermanently'){if(!deleteBookmark(db,userId,item.id,item.version))throw new Error('Bookmark changed.');}else{const patch:any={};if(action.type==='markRead')patch.readState='read';if(action.type==='markUnread')patch.readState='unread';if(action.type==='archive')patch.archived=true;if(action.type==='restore')patch.archived=false;if(action.type==='addTags')patch.tagIds=[...new Set([...item.tagIds,...(action.tagIds||[])])];if(action.type==='removeTags')patch.tagIds=item.tagIds.filter(id=>!(action.tagIds||[]).includes(id));updateBookmark(db,userId,item.id,item.version,patch);}succeeded++;}catch(error){failures.push({bookmarkId:item.id,reason:error instanceof Error?error.message:'Action failed.'});}}return{matchedCount:items.length,succeededCount:succeeded,failedCount:failures.length,failures,libraryRevision:currentRevision(db,userId)};})();}

