item.notesMarkdown&&<button className="text-button" onClick={()=>setOpen(!open)}><Icon name="eye"/>{open?'Hide notes':'Notes'}</button>}<div className="spacer"/><button className="icon-button" title="Edit" onClick={onEdit}><Icon name="edit"/></button><button className="icon-button" title={item.archived?'Restore':'Archive'} onClick={()=>patch({archived:!item.archived})}><Icon name="archive"/></button><button className="icon-button danger" title="Delete permanently" onClick={remove}><Icon name="trash"/></button></footer></div></article>}

