export type SearchNode =
  | { type: 'text'; value: string; start: number; end: number }
  | { type: 'phrase'; value: string; start: number; end: number }
  | { type: 'tag'; value: string; start: number; end: number }
  | { type: 'not'; child: SearchNode }
  | { type: 'and' | 'or'; children: SearchNode[] };

type Token = { type: 'term' | 'phrase' | 'tag' | 'and' | 'or' | 'not' | 'lp' | 'rp'; value: string; start: number; end: number };

export class SearchSyntaxError extends Error {
  constructor(message: string, public start: number, public end: number) { super(message); }
}

export function tokenize(query: string): Token[] {
  if (query.length > 1000) throw new SearchSyntaxError('Search is limited to 1,000 characters.', 1000, query.length);
  const tokens: Token[] = [];
  let i = 0;
  const quoted = (): { value: string; start: number; end: number } => {
    const start = i++;
    let value = '';
    while (i < query.length && query[i] !== '"') value += query[i++];
    if (query[i] !== '"') throw new SearchSyntaxError('Close the quoted phrase with another quotation mark.', start, query.length);
    i++;
    return { value, start, end: i };
  };
  while (i < query.length) {
    if (/\s/u.test(query[i])) { i++; continue; }
    const start = i;
    if (query[i] === '(') { tokens.push({ type: 'lp', value: '(', start, end: ++i }); continue; }
    if (query[i] === ')') { tokens.push({ type: 'rp', value: ')', start, end: ++i }); continue; }
    if (query[i] === '"') { const q = quoted(); tokens.push({ type: 'phrase', ...q }); continue; }
    if (query.slice(i, i + 4).toLowerCase() === 'tag:' && (i + 4 === query.length || !/\s/u.test(query[i + 4]))) {
      i += 4;
      let value = '';
      if (query[i] === '"') value = quoted().value;
      else while (i < query.length && !/[\s()]/u.test(query[i])) value += query[i++];
      if (!value) throw new SearchSyntaxError('Add a tag name after tag:.', start, i);
      tokens.push({ type: 'tag', value, start, end: i }); continue;
    }
    let value = '';
    while (i < query.length && !/[\s()]/u.test(query[i])) value += query[i++];
    const upper = value.toUpperCase();
    const type = upper === 'AND' ? 'and' : upper === 'OR' ? 'or' : upper === 'NOT' ? 'not' : 'term';
    tokens.push({ type, value, start, end: i });
    if (tokens.length > 100) throw new SearchSyntaxError('Search is limited to 100 terms and operators.', start, i);
  }
  return tokens;
}

export function parseSearch(query: string): SearchNode | null {
  const tokens = tokenize(query);
  if (!tokens.length) return null;
  let index = 0;
  let depth = 0;
  const peek = () => tokens[index];
  const startsPrimary = (t?: Token) => !!t && ['term', 'phrase', 'tag', 'lp', 'not'].includes(t.type);
  const primary = (): SearchNode => {
    const token = peek();
    if (!token) throw new SearchSyntaxError('The search ends before the expression is complete.', query.length, query.length);
    if (token.type === 'not') { index++; return { type: 'not', child: primary() }; }
    if (token.type === 'lp') {
      if (++depth > 10) throw new SearchSyntaxError('Search can use at most 10 levels of parentheses.', token.start, token.end);
      index++; const node = or();
      if (peek()?.type !== 'rp') throw new SearchSyntaxError('Close this parenthesized expression.', token.start, query.length);
      index++; depth--; return node;
    }
    if (token.type === 'term' || token.type === 'phrase' || token.type === 'tag') { index++; return { type: token.type === 'term' ? 'text' : token.type, value: token.value, start: token.start, end: token.end } as SearchNode; }
    throw new SearchSyntaxError(`Unexpected ${token.value || token.type}.`, token.start, token.end);
  };
  const and = (): SearchNode => {
    const children: SearchNode[] = [primary()];
    while (peek()?.type === 'and' || peek()?.type === 'not' || startsPrimary(peek())) {
      if (peek()?.type === 'and') { const op = tokens[index++]; if (!startsPrimary(peek())) throw new SearchSyntaxError('Add a term after AND.', op.start, op.end); }
      if (peek()?.type === 'not') { index++; children.push({ type: 'not', child: primary() }); }
      else children.push(primary());
    }
    return children.length === 1 ? children[0] : { type: 'and', children };
  };
  const or = (): SearchNode => {
    const children: SearchNode[] = [and()];
    while (peek()?.type === 'or') {
      const op = tokens[index++]; if (!startsPrimary(peek())) throw new SearchSyntaxError('Add a term after OR.', op.start, op.end);
      children.push(and());
    }
    return children.length === 1 ? children[0] : { type: 'or', children };
  };
  const result = or();
  if (index < tokens.length) throw new SearchSyntaxError(`Unexpected ${tokens[index].value}.`, tokens[index].start, tokens[index].end);
  return result;
}
import type { Db } from '../db/client.js';
import type { BookmarkDto, SearchCriteria } from '../../shared/types.js';
import { normalizeName } from '../../shared/normalization.js';
import { mapBookmark } from '../db/repositories/bookmarks.js';
import { parseSearch, type SearchNode } from './parser.js';

type Row = Record<string, any>;
const intersect = (a: Set<number>, b: Set<number>) => new Set([...a].filter((id) => b.has(id)));
const union = (a: Set<number>, b: Set<number>) => new Set([...a, ...b]);
const subtract = (a: Set<number>, b: Set<number>) => new Set([...a].filter((id) => !b.has(id)));

function universe(db: Db, userId: number, criteria: SearchCriteria): Set<number> {
  const where = ['b.user_id=?']; const values: unknown[] = [userId];
  if (criteria.location === 'archive') where.push('b.archived_at IS NOT NULL'); else where.push('b.archived_at IS NULL');
  if (criteria.location === 'unread') where.push("b.read_state='unread'");
  if (criteria.readState) { where.push('b.read_state=?'); values.push(criteria.readState); }
  if (criteria.collectionId) { where.push('c.public_id=?'); values.push(criteria.collectionId); }
  for (const tagId of criteria.tagIds) { where.push('EXISTS(SELECT 1 FROM bookmark_tags fx JOIN tags ft ON ft.id=fx.tag_id WHERE fx.bookmark_id=b.id AND ft.user_id=b.user_id AND ft.public_id=?)'); values.push(tagId); }
  return new Set((db.prepare(`SELECT b.id FROM bookmarks b LEFT JOIN collections c ON c.id=b.collection_id WHERE ${where.join(' AND ')}`).all(...values) as Row[]).map((row) => row.id));
}

function leaf(db: Db, userId: number, node: Extract<SearchNode, { type: 'text' | 'phrase' | 'tag' }>): Set<number> {
  if (node.type === 'tag') {
    const key = normalizeName(node.value).key;
    return new Set((db.prepare(`SELECT bt.bookmark_id id FROM bookmark_tags bt JOIN tags t ON t.id=bt.tag_id WHERE t.user_id=? AND t.name_key=?`).all(userId, key) as Row[]).map((row) => row.id));
  }
  const escaped = node.value.replace(/"/g, '""');
  if (!escaped.trim()) return new Set();
  try { return new Set((db.prepare(`SELECT b.id FROM bookmark_fts f JOIN bookmarks b ON b.id=f.rowid WHERE b.user_id=? AND bookmark_fts MATCH ?`).all(userId, `"${escaped}"`) as Row[]).map((row) => row.id)); }
  catch { return new Set(); }
}

function evaluate(db: Db, userId: number, node: SearchNode, all: Set<number>): Set<number> {
  if (node.type === 'text' || node.type === 'phrase' || node.type === 'tag') return intersect(all, leaf(db, userId, node));
  if (node.type === 'not') return subtract(all, evaluate(db, userId, node.child, all));
  const values = node.children.map((child) => evaluate(db, userId, child, all));
  return values.slice(1).reduce((result, value) => node.type === 'and' ? intersect(result, value) : union(result, value), values[0]);
}

export function searchBookmarks(db: Db, userId: number, criteria: SearchCriteria, cursor: number, limit: number): { items: BookmarkDto[]; total: number; nextCursor: string | null } {
  const all = universe(db, userId, criteria);
  const ast = parseSearch(criteria.query);
  const ids = ast ? evaluate(db, userId, ast, all) : all;
  if (!ids.size) return { items: [], total: 0, nextCursor: null };
  const placeholders = [...ids].map(() => '?').join(',');
  const rows = db.prepare(`SELECT b.*,c.public_id collection_public_id,c.name collection_name FROM bookmarks b LEFT JOIN collections c ON c.id=b.collection_id WHERE b.id IN (${placeholders})`).all(...ids) as Row[];
  rows.sort((a, b) => criteria.sort === 'title' ? a.title_sort_key.localeCompare(b.title_sort_key) || a.id-b.id : criteria.sort === 'oldest' ? a.created_at.localeCompare(b.created_at) || a.id-b.id : b.created_at.localeCompare(a.created_at) || b.id-a.id);
  const page = rows.slice(cursor, cursor + limit);
  return { items: page.map((row) => mapBookmark(db, row)), total: rows.length, nextCursor: cursor + limit < rows.length ? Buffer.from(String(cursor + limit)).toString('base64url') : null };
}

export function decodeCursor(value?: string): number {
  if (!value) return 0;
  const number = Number(Buffer.from(value, 'base64url').toString());
  return Number.isInteger(number) && number >= 0 ? number : 0;
}
export type ReadState = 'unread' | 'read';
export type Location = 'active' | 'unread' | 'archive';
export type Sort = 'newest' | 'oldest' | 'title';
export type MetadataStatus = 'complete' | 'partial' | 'unavailable' | 'blocked' | 'timeout';

